package com.dawnrise.academic.studentleave;

import com.dawnrise.academic.security.AuthenticatedAcademicActor;import com.dawnrise.academic.studentleave.StudentLeaveDtos.*;import jakarta.validation.Valid;import org.springframework.http.*;import org.springframework.security.access.prepost.PreAuthorize;import org.springframework.security.oauth2.server.resource.authentication.JwtAuthenticationToken;import org.springframework.web.bind.annotation.*;import org.springframework.web.multipart.MultipartFile;import java.util.*;
import java.time.LocalDate;

@RestController @RequestMapping("/api/v1/student-leave")
@PreAuthorize("@academicTenantSecurity.hasOrganization(authentication)")
public class StudentLeaveController{
 private final StudentLeaveService service;public StudentLeaveController(StudentLeaveService service){this.service=service;}
 @PostMapping("/self/preview") @PreAuthorize("hasAuthority('STUDENT_LEAVE_SELF')") public Preview selfPreview(JwtAuthenticationToken a,@Valid@RequestBody RequestInput in){return service.preview(org(a),user(a),user(a),InitiatorType.STUDENT,in);}
 @PostMapping("/self/requests") @PreAuthorize("hasAuthority('STUDENT_LEAVE_SELF')") public View selfCreate(JwtAuthenticationToken a,@Valid@RequestBody RequestInput in){return service.create(org(a),user(a),user(a),InitiatorType.STUDENT,in);}
 @PostMapping("/guardian/students/{student}/preview") @PreAuthorize("hasAuthority('STUDENT_LEAVE_GUARDIAN')") public Preview guardianPreview(JwtAuthenticationToken a,@PathVariable long student,@Valid@RequestBody RequestInput in){return service.preview(org(a),user(a),student,InitiatorType.GUARDIAN,in);}
 @PostMapping("/guardian/students/{student}/requests") @PreAuthorize("hasAuthority('STUDENT_LEAVE_GUARDIAN')") public View guardianCreate(JwtAuthenticationToken a,@PathVariable long student,@Valid@RequestBody RequestInput in){return service.create(org(a),user(a),student,InitiatorType.GUARDIAN,in);}
 @GetMapping("/requests/self") @PreAuthorize("hasAnyAuthority('STUDENT_LEAVE_SELF','STUDENT_LEAVE_GUARDIAN')") public List<View>mine(JwtAuthenticationToken a){return service.mine(org(a),user(a));}
 @PutMapping("/requests/{id}") @PreAuthorize("hasAnyAuthority('STUDENT_LEAVE_SELF','STUDENT_LEAVE_GUARDIAN')") public View revise(JwtAuthenticationToken a,@PathVariable long id,@RequestParam long expectedVersion,@Valid@RequestBody RequestInput in){return service.revise(org(a),user(a),id,expectedVersion,in);}
 @PostMapping("/requests/{id}/submit") @PreAuthorize("hasAnyAuthority('STUDENT_LEAVE_SELF','STUDENT_LEAVE_GUARDIAN')") public View submit(JwtAuthenticationToken a,@PathVariable long id,@Valid@RequestBody VersionInput in){return service.submit(org(a),user(a),id,in.expectedVersion());}
 @PostMapping("/requests/{id}/withdraw") @PreAuthorize("hasAnyAuthority('STUDENT_LEAVE_SELF','STUDENT_LEAVE_GUARDIAN')") public View withdraw(JwtAuthenticationToken a,@PathVariable long id,@Valid@RequestBody VersionInput in){return service.withdraw(org(a),user(a),id,in.expectedVersion());}
 @PostMapping("/requests/{id}/cancel") @PreAuthorize("hasAnyAuthority('STUDENT_LEAVE_SELF','STUDENT_LEAVE_GUARDIAN')") public View cancel(JwtAuthenticationToken a,@PathVariable long id,@Valid@RequestBody CancelInput in){return service.cancel(org(a),user(a),id,in);}
 @GetMapping("/requests/{id}/audit") @PreAuthorize("hasAnyAuthority('STUDENT_LEAVE_SELF','STUDENT_LEAVE_GUARDIAN','STUDENT_LEAVE_APPROVE')") public List<Audit> audit(JwtAuthenticationToken a,@PathVariable long id){return service.audit(org(a),user(a),id);}
 @GetMapping("/requests/{id}/attachments") @PreAuthorize("hasAnyAuthority('STUDENT_LEAVE_SELF','STUDENT_LEAVE_GUARDIAN','STUDENT_LEAVE_APPROVE')") public List<Attachment> attachments(JwtAuthenticationToken a,@PathVariable long id){return service.attachments(org(a),user(a),id);}
 @GetMapping("/calendar/self") @PreAuthorize("hasAnyAuthority('STUDENT_LEAVE_SELF','STUDENT_LEAVE_GUARDIAN')") public List<View> calendar(JwtAuthenticationToken a,@RequestParam LocalDate start,@RequestParam LocalDate end){return service.calendar(org(a),user(a),start,end);}
 @GetMapping("/admin/policy") @PreAuthorize("hasAuthority('STUDENT_LEAVE_ADMIN')") public PolicyView policy(JwtAuthenticationToken a){return service.policy(org(a));}
 @PutMapping("/admin/policy") @PreAuthorize("hasAuthority('STUDENT_LEAVE_ADMIN')") public PolicyView updatePolicy(JwtAuthenticationToken a,@Valid@RequestBody PolicyInput in){return service.updatePolicy(org(a),in);}
 @GetMapping("/admin/approver-mappings") @PreAuthorize("hasAuthority('STUDENT_LEAVE_ADMIN')") public List<ApproverMappingView> approverMappings(JwtAuthenticationToken a){return service.approverMappings(org(a));}
 @PostMapping("/admin/approver-mappings") @PreAuthorize("hasAuthority('STUDENT_LEAVE_ADMIN')") public ApproverMappingView createApproverMapping(JwtAuthenticationToken a,@Valid@RequestBody ApproverMappingInput in){return service.createApproverMapping(org(a),in);}
 @PutMapping("/admin/approver-mappings/{mappingId}") @PreAuthorize("hasAuthority('STUDENT_LEAVE_ADMIN')") public ApproverMappingView updateApproverMapping(JwtAuthenticationToken a,@PathVariable long mappingId,@Valid@RequestBody ApproverMappingInput in){return service.updateApproverMapping(org(a),mappingId,in);}
 @GetMapping("/admin/attendance-conflicts") @PreAuthorize("hasAuthority('STUDENT_LEAVE_ADMIN')") public List<AttendanceConflict> attendanceConflicts(JwtAuthenticationToken a){return service.attendanceConflicts(org(a));}
 @PostMapping("/admin/attendance-conflicts/{projectionId}/reconcile") @PreAuthorize("hasAuthority('STUDENT_LEAVE_ADMIN')") public void reconcileAttendance(JwtAuthenticationToken a,@PathVariable long projectionId,@Valid@RequestBody ReconciliationInput in){service.reconcileAttendance(org(a),user(a),projectionId,in);}
 @GetMapping("/approvals") @PreAuthorize("hasAnyAuthority('STUDENT_LEAVE_APPROVE','STUDENT_LEAVE_GUARDIAN')") public List<View>queue(JwtAuthenticationToken a){return service.queue(org(a),user(a));}
 @PostMapping("/approvals/{id}/decision") @PreAuthorize("hasAnyAuthority('STUDENT_LEAVE_APPROVE','STUDENT_LEAVE_GUARDIAN')") public View decide(JwtAuthenticationToken a,@PathVariable long id,@Valid@RequestBody DecisionInput in){return service.decide(org(a),user(a),id,in);}
 @PostMapping(value="/requests/{id}/attachments",consumes=MediaType.MULTIPART_FORM_DATA_VALUE) @PreAuthorize("hasAnyAuthority('STUDENT_LEAVE_SELF','STUDENT_LEAVE_GUARDIAN')") public Attachment upload(JwtAuthenticationToken a,@PathVariable long id,@RequestPart MultipartFile file){return service.upload(org(a),user(a),id,file);}
 @GetMapping("/requests/{id}/attachments/{attachment}") @PreAuthorize("hasAnyAuthority('STUDENT_LEAVE_SELF','STUDENT_LEAVE_GUARDIAN','STUDENT_LEAVE_APPROVE')") public ResponseEntity<byte[]>download(JwtAuthenticationToken a,@PathVariable long id,@PathVariable UUID attachment){var d=service.download(org(a),user(a),id,attachment);return ResponseEntity.ok().contentType(MediaType.parseMediaType(d.contentType())).header(HttpHeaders.CONTENT_DISPOSITION,ContentDisposition.attachment().filename(d.name()).build().toString()).header("X-Content-Type-Options","nosniff").body(d.content());}
 @DeleteMapping("/requests/{id}/attachments/{attachment}") @PreAuthorize("hasAnyAuthority('STUDENT_LEAVE_SELF','STUDENT_LEAVE_GUARDIAN')") public void remove(JwtAuthenticationToken a,@PathVariable long id,@PathVariable UUID attachment){service.removeAttachment(org(a),user(a),id,attachment);}
 private long org(JwtAuthenticationToken a){return AuthenticatedAcademicActor.organizationId(a);}private long user(JwtAuthenticationToken a){return AuthenticatedAcademicActor.userId(a);}
}
